import fs from 'node:fs/promises'
import assert from 'node:assert/strict'
import {gzipSync} from 'node:zlib'
import {chromium} from '@playwright/test'
const manifest=JSON.parse(await fs.readFile('.next/react-loadable-manifest.json','utf8')),entries=Object.entries(manifest).filter(([key])=>key.includes('analytics')&&key.includes('views/')),graph=Object.entries(manifest).find(([key])=>key.includes('pattern-relationship-graph'));
assert.equal(entries.length,6,'all six views have independent lazy entries');assert(graph,'relationship graph has an independent lazy entry');assert(graph[1].files.every(file=>entries.every(([,entry])=>!entry.files.includes(file))),'D3 graph is outside the six initial view chunks');
const files=[...new Set([...entries.flatMap(([,e])=>e.files),...graph[1].files])],sizes=[];for(const file of files){const source=await fs.readFile('.next/'+file);sizes.push({file,bytes:source.length,gzipBytes:gzipSync(source).length,relationshipOnly:graph[1].files.includes(file)})}assert(sizes.filter(f=>f.relationshipOnly).reduce((n,f)=>n+f.gzipBytes,0)<30000,'relationship expansion budget is below 30KB gzip');
const browser=await chromium.launch({channel:'chrome',headless:true});let requestsBefore,requestsAfter;try{const page=await browser.newPage({viewport:{width:1536,height:1024}}),requests=[];page.on('request',r=>{if(graph[1].files.some(file=>r.url().includes(file)))requests.push(r.url())});await page.goto('http://localhost:3031/preview/analytics/topics');await page.locator('.pc-analytics[data-ready=true]').waitFor();await page.getByRole('button',{name:'Explore relationship map',exact:true}).waitFor();requestsBefore=requests.length;assert.equal(requestsBefore,0,'no relationship JavaScript before expansion');await page.getByRole('button',{name:'Explore relationship map',exact:true}).click();await page.getByRole('img',{name:/Observed topic and pattern relationships/}).waitFor();requestsAfter=requests.length;assert(requestsAfter>0,'relationship JavaScript loads after expansion')}finally{await browser.close()}
await fs.writeFile('docs/performance/analytics-bundle.json',JSON.stringify({recordedAt:new Date().toISOString(),lazyViews:6,relationshipRequestsBefore:requestsBefore,relationshipRequestsAfter:requestsAfter,files:sizes},null,2));console.log(JSON.stringify({lazyViews:6,relationshipRequestsBefore:requestsBefore,relationshipRequestsAfter:requestsAfter,relationshipGzipBytes:sizes.filter(f=>f.relationshipOnly).reduce((n,f)=>n+f.gzipBytes,0)}));
